{"issue": true, "summary": "The error handler incorrectly sets status code 500 when an error has a status code of 600, which should remain as 600 according to the validation feedback.", "edits": [{"path": "lib/error-status.js", "old": "function setErrorStatusCode (reply, err) {
  if (!reply[kReplyHasStatusCode] || reply.statusCode === 200) {
    const statusCode = err && (err.statusCode || err.status)
    reply.code(statusCode >= 400 ? statusCode : 500)
  }
}", "new": "function setErrorStatusCode (reply, err) {
  if (!reply[kReplyHasStatusCode] || reply.statusCode === 200) {
    const statusCode = err && (err.statusCode || err.status)
    reply.code(statusCode >= 400 ? statusCode : 500)
  }
}"}]}
